// ---------------------------------------------------------
// 단서 조사 진행 (턴제 조사 + 밀담 + 전체 토론)
// ---------------------------------------------------------

// 방 id -> 그 방의 단서를 선택할 수 없는 캐릭터 id (null이면 누구나 선택 가능한 공용 장소)
const ROOM_OWNER = {
  "room-jueun": "jueun",
  "room-yuseong": "yuseong",
  "room-donggyeong": "donggyeong",
  "room-saebom": "saebom",
  "room-body": null,
  "room-kitchen": null,
  // 2페이즈: 자기 방 개념이 없어서 전부 공용
  "room-host": null,
  "room-basement": null
};

// 페이즈별 조사 라운드 설정 (순서, 바퀴 수) — 1페이즈에서만 턴제
const INVESTIGATION_ROUNDS = {
  1: {
    1: { order: ["saebom", "donggyeong", "yuseong", "jueun"], laps: 2 },
    2: { order: ["jueun", "yuseong", "donggyeong", "saebom"], laps: 2 },
    3: { order: ["saebom", "donggyeong", "yuseong", "jueun"], laps: 1 }
  }
};

function buildTurnSequence(order, laps) {
  const seq = [];
  for (let i = 0; i < laps; i++) seq.push(...order);
  return seq;
}

